func kClosest(_ points: [[Int]], _ k: Int) -> [[Int]] {
    func d(_ p: [Int]) -> Int { p[0] * p[0] + p[1] * p[1] }
    var heap = Heap<[Int]>({ d($0) > d($1) })     // farthest on top
    for p in points {
        heap.push(p)
        if heap.count > k { heap.pop() }
    }
    var result: [[Int]] = []
    while let p = heap.pop() { result.append(p) }
    return result
}
